import { useState } from 'react'
import { PageHeader } from '@/features/shell/PageHeader'
import { Search } from 'lucide-react'

export function SearchPage() {
  const [query, setQuery] = useState('')

  return (
    <div className="flex flex-col h-full overflow-hidden">
      <PageHeader title="Search" />
      <div className="flex-1 overflow-y-auto p-6">
        <div className="max-w-2xl mx-auto">
          <div className="flex items-center gap-2 rounded-xl border border-border bg-surface px-4 py-3 mb-6 focus-within:border-accent">
            <Search size={16} className="text-muted-foreground" />
            <input
              autoFocus
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder="Search projects, objectives, people..."
              className="flex-1 bg-transparent text-sm outline-none"
            />
          </div>
          {query.length === 0 ? (
            <p className="text-sm text-muted-foreground text-center mt-8">Start typing to search across the ecosystem</p>
          ) : (
            <p className="text-sm text-muted-foreground text-center mt-8">
              Connect the Vox integration layer to enable semantic search.
            </p>
          )}
        </div>
      </div>
    </div>
  )
}
